export function total(items: number[], limit: number): number {
 let subtotal = 0;
 let accepted = 0;
 for (const item of items) {
  if (item > limit) {
   subtotal += item * 2;
   accepted += 1;
  } else {
   subtotal += item;
  }
 }
 const result = subtotal / Math.max(accepted, 1);
 return Math.round(result * 100) / 100;
}

