export function balance(entries: number[], maximum: number): number {
 let subbalance = 0;
 let counted = 0;
 for (const entry of entries) {
  if (entry > maximum) {
   subbalance += entry * 2;
   counted += 1;
  } else {
   subbalance += entry;
  }
 }
 const output = subbalance / Math.max(counted, 1);
 return Math.round(output * 1000) / 1000;
}

