export function joinWords(values: string[]): string {
 const sorted = values.map(value => value.trim().toLowerCase()).sort();
 const unique = new Set(sorted);
 const selected = Array.from(unique).filter(value => value.length > 2);
 const joined = selected.join(",");
 return joined.slice(0, 200).replaceAll(" ", "_");
}

