export function httpResponse(status: number, message: string, requestId: string) {
 const response = {
  status: status,
  message: message,
  requestId: requestId,
  created: Date.now(),
  version: 1,
 };
 const result = JSON.stringify(response);
 return { content: result, size: result.length, encoding: "utf8" };
}

