export function notification(priority: number, title: string, recipient: string) {
 const notice = {
  priority: priority,
  title: title,
  recipient: recipient,
  created: Date.now(),
  version: 2,
 };
 const display = JSON.stringify(notice);
 return { text: display, length: display.length, charset: "utf8" };
}
